const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',scan:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M3 12h18"/><rect x="7" y="7" width="10" height="10" rx="2"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m21 15-5-5L5 21"/>',camera:'<path d="M8 5 10 3h4l2 2h4a1 1 0 0 1 1 1v13H3V6a1 1 0 0 1 1-1Z"/><circle cx="12" cy="12" r="4"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',cpu:'<rect x="6" y="6" width="12" height="12" rx="2"/><rect x="9" y="9" width="6" height="6"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/>',book:'<path d="M12 5c-3-2-7-2-10 0v15c3-2 7-2 10 0 3-2 7-2 10 0V5c-3-2-7-2-10 0Zm0 0v15"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',arrow:'<path d="m9 5 7 7-7 7"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m5 12 4 4L19 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M14 2H4v20h16V8Zm0 0v6h6M8 13h8m-8 4h8"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plane:'<path d="m2 12 7-2 3-8 2 1-1 7 8 4-1 2-7-1-2 6H9v-7l-7 1Z"/>'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>new Date().toISOString();
const localDate=(date)=>new Date(date).toLocaleString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
const uid=(prefix)=>`${prefix}-${new Date().toISOString().slice(0,10).replaceAll('-','')}-${crypto.randomUUID().slice(0,6).toUpperCase()}`;
const btn=(text,action,kind='',ic='')=>`<button type="button" class="btn ${kind}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
let db,state={records:[],dataset:[],settings:{company:'내부 공급용 워크스페이스',station:'검사 스테이션 01',classes:['양품','스크래치','찍힘','오염'],threshold:80,modelUrl:''}};
let view='inspect',source='upload',selected=null,result=null,stream=null,model=null,modelName='',modelOrigin='',busy=false,search='',filter='all',demoType='스크래치';
let inspectionForm={part:'',lot:'',area:'표면 / 가공면',inspector:'김민석',verdict:'미검토',notes:''};
let notificationTimer;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(notificationTimer);notificationTimer=setTimeout(()=>el.classList.remove('show'),4600)}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('aeroscope-workspace-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function load(){db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readonly');const req=tx.objectStore('workspace').get('state');req.onsuccess=()=>{if(req.result)state=req.result;resolve()};req.onerror=()=>reject(req.error)})}
async function persist(){return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(state,'state');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error('브라우저 저장소에 저장하지 못했습니다.'));tx.onabort=()=>reject(tx.error||new Error('저장이 중단되었습니다.'))})}
async function mutate(fn){const before=structuredClone(state);try{fn();await persist()}catch(e){state=before;throw e}}
function stopCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function navigate(next){stopCamera();view=next;search='';filter='all';render();window.scrollTo({top:0,behavior:'smooth'})}
const names={overview:'워크스페이스',inspect:'외관 품질검사',dataset:'데이터 수집',history:'검사 이력',model:'AI 모델 연결',guide:'도입 가이드',settings:'워크스페이스 설정'};
function render(){
 const nav=[['overview','grid'],['inspect','scan'],['dataset','layers'],['history','clock'],['model','cpu'],['guide','book']];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-symbol">${icon('plane')}</div><div><div class="brand-name">AEROSCOPE</div><small>MANUFACTURING QUALITY</small></div></div><nav><div class="nav-caption">WORKSPACE</div>${nav.map(([key,ic])=>`<button class="nav-item ${view===key?'active':''}" data-nav="${key}">${icon(ic)}${names[key]}</button>`).join('')}<div class="nav-divider"></div><button class="nav-item ${view==='settings'?'active':''}" data-nav="settings">${icon('settings')}워크스페이스 설정</button></nav><div class="sidebar-bottom"><div class="deployment"><strong><span class="dot"></span>내부 공급용 시제품</strong>학습 데이터 · 검증 모델 미포함<br>기능 검증과 현장 데이터 수집 준비</div><div class="user"><span class="avatar">KM</span><div>김민석<small>산학프로젝트 · 2026210300</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${icon('grid')}<span>${esc(state.settings.company)}</span><span>/</span><strong>${names[view]}</strong></div><div class="topright"><span class="date">${new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric'})}</span><span class="pill ${model?'':'gray'}"><span class="dot"></span>${model?'모델 연결됨':'모델 연결 대기'}</span></div></header><div class="content">${({inspect:inspectionView,overview:overviewView,dataset:datasetView,history:historyView,model:modelView,guide:guideView,settings:settingsView}[view])()}<footer class="footer"><span>AEROSCOPE / 항공제조 외관 품질검사</span><span>브라우저 내 저장 · ${esc(state.settings.station)} · 학습 데이터는 공급 후 기업이 수집</span></footer></div></main></div>`;
 bind();if(view==='inspect')renderStage();
}
function head(title,sub,buttons=''){return `<div class="page-head"><div><div class="eyebrow">AEROSCOPE QUALITY WORKSPACE</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-buttons">${buttons}</div></div>`}
function stats(){const verified=state.records.filter(r=>['양품','불량'].includes(r.review.verdict)).length;return `<div class="stats">${[
 ['검사 기록',state.records.length,'건','저장된 촬영 · 관찰 기록','scan'],
 ['검토 대기',state.records.length-verified,'건','담당자 최종 검토 필요','clock'],
 ['수집 이미지',state.dataset.length,'장','실제 수집과 합성 시연 자료 구분','layers'],
 ['AI 모델',model?'연결됨':'미연결','','기업 학습 모델을 연결해 주세요','cpu']
 ].map(([title,value,unit,foot,ic])=>`<div class="stat"><div class="stat-top">${title}${icon(ic)}</div><div class="stat-value" ${!unit?'style="font-size:21px"':''}>${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div></div>`).join('')}</div>`}
function inspectionView(){return `${head('외관 품질검사','사진 한 장에서 검토 기록까지. 촬영하고, 확인하고, 다음 검사를 위한 데이터를 모으세요.',btn('합성 샘플로 시연','sample','','image')+btn('새 검사','new','primary','plus'))}${stats()}<div class="workspace"><section class="card"><div class="card-head"><h2>검사 이미지</h2><span class="minor">VISUAL INSPECTION</span></div><div class="card-body"><div class="tabs"><button class="tab ${source==='upload'?'active':''}" data-action="source-upload">이미지 업로드</button><button class="tab ${source==='camera'?'active':''}" data-action="source-camera">실시간 카메라</button></div><div class="stage" id="stage"></div><div class="stage-actions"><span class="file-note">JPG · PNG · WEBP / 최대 12 MB<br>촬영 이미지는 이 브라우저에 보관됩니다.</span><div class="actions">${source==='camera'?btn(stream?'촬영':'카메라 연결',stream?'capture':'camera','', 'camera')+ (stream?btn('종료','stop','','stop'):''):btn('사진 선택','upload','','upload')}</div></div><div class="form-grid"><label class="field">부품 번호 <span class="required">*</span><input data-form="part" id="part-number" placeholder="예: BRKT-001" value="${esc(inspectionForm.part)}" maxlength="100"></label><label class="field">LOT / 일련번호 <span class="required">*</span><input data-form="lot" placeholder="예: LOT-2026-001" value="${esc(inspectionForm.lot)}" maxlength="100"></label><label class="field">촬영 부위<select data-form="area">${['표면 / 가공면','체결부 / 리벳','모서리 / 홀','도장 / 코팅','기타'].map(x=>`<option ${x===inspectionForm.area?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">검사자 <span class="required">*</span><input data-form="inspector" placeholder="검사자 이름" value="${esc(inspectionForm.inspector)}" maxlength="60"></label></div></div></section><div class="stack"><section class="card"><div class="card-head"><h2>AI 판독 지원</h2><span class="pill ${result?.kind==='demo'?'amber':model?'':'gray'}">${result?.kind==='demo'?'시연 결과':model?'연결됨':'대기'}</span></div><div class="card-body"><div class="model-status"><span class="model-icon">${icon('cpu')}</span><div><strong>${model?esc(modelName):'학습 모델이 연결되지 않았습니다'}</strong><small>${model?'이미지 분류 모델 · 담당자 검토 필요':'기업 데이터 수집 · 학습 후 연결할 수 있습니다'}</small></div></div><div id="result">${resultMarkup()}</div><div class="inline-note">${result?.kind==='demo'?'합성 샘플의 고정 시나리오입니다. 실제 이미지 분석이나 성능 평가 결과가 아닙니다.':'현재 데이터셋과 검증된 모델은 포함되어 있지 않습니다. 모델 출력은 최종 품질 판정을 대신하지 않습니다.'}</div><div class="model-actions">${btn('모델 연결','go-model','','cpu')}${btn(busy?'분석 중…':'AI 분석', 'predict','primary','scan')}</div>${selected?.origin==='synthetic'?`<div class="divider"></div><label class="field">발표용 시연 시나리오<select id="demo-type">${['양품','스크래치','찍힘'].map(x=>`<option ${x===demoType?'selected':''}>${x}</option>`).join('')}</select></label><div style="margin-top:10px">${btn('선택한 시나리오 시연','simulate','small','')}</div>`:''}</div></section><section class="card"><div class="card-head"><h2>검토 및 기록</h2><span class="minor">HUMAN REVIEW</span></div><div class="card-body"><div class="review-heading">${icon('shield')}최종 검토는 담당자가 수행합니다</div><div class="form-grid"><label class="field">검토 결과<select data-form="verdict">${['미검토','양품','불량','재검토'].map(x=>`<option ${x===inspectionForm.verdict?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">수집 라벨<select id="collection-label">${['미분류',...state.settings.classes].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field full">관찰 내용 · 검토 의견<textarea data-form="notes" placeholder="외관 상태, 촬영 조건, 추가 확인 사항을 기록하세요." maxlength="3000">${esc(inspectionForm.notes)}</textarea></label></div><div class="review-actions">${btn('수집함에 추가','collect','','layers')}${btn('검사 기록 저장','save','dark','check')}</div><p class="smalltext" style="margin:10px 0 0">검사 기록과 학습용 수집함은 별도로 관리됩니다.</p></div></section></div></div><div class="section-head"><h2>최근 검사 기록</h2><a href="#history" data-nav="history">전체 이력 보기 →</a></div><div class="card table-wrap">${recordsTable(state.records.slice().reverse().slice(0,4))}</div>`}
function resultMarkup(){if(!result)return `<div class="result-box"><div class="result-icon">${icon('scan')}</div><strong>판독 준비 중</strong><p>${selected?'사진이 준비되었습니다. 모델을 연결하거나 합성 샘플 시연을 실행하세요.':'이미지를 선택하거나 카메라로 촬영해 주세요.'}</p></div>`;return `<div class="result-box ready"><span class="pill ${result.kind==='demo'?'amber':'gray'}">${result.kind==='demo'?'미리 정의한 시연값':'모델 제안 · 미검증'}</span><div class="result-title">${esc(result.label)}</div><p>${esc(result.note)}</p>${(result.scores||[]).map(s=>`<div class="score"><div class="labels"><span>${esc(s.className)}</span><span>${(s.probability*100).toFixed(1)}%</span></div><div class="bar"><span style="width:${Math.max(0,Math.min(100,s.probability*100))}%"></span></div></div>`).join('')}</div>`}
function recordsTable(rows,emptyText='아직 저장된 검사 기록이 없습니다. 사진과 관찰 내용을 첫 기록으로 남겨보세요.'){return `<table><thead><tr><th>기록 번호</th><th>부품 / LOT</th><th>촬영 부위</th><th>AI 제안</th><th>검토 상태</th><th>검사 일시</th><th></th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><span class="badge-code">${esc(r.id)}</span></td><td>${esc(r.part)}<div class="smalltext">${esc(r.lot)}</div></td><td>${esc(r.area)}</td><td>${r.ai?esc(r.ai.label):'모델 미연결'}${r.ai?.kind==='demo'?'<div class="smalltext">시연</div>':''}</td><td><span class="pill ${r.review.verdict==='불량'?'red':r.review.verdict==='양품'?'':'amber'}">${esc(r.review.verdict)}</span></td><td>${localDate(r.createdAt)}</td><td><button class="btn small" data-record="${esc(r.id)}">상세</button></td></tr>`).join(''):`<tr><td colspan="7" class="table-empty">${esc(emptyText)}</td></tr>`}</tbody></table>`}
function renderStage(){const el=$('#stage');if(!el)return;if(stream){el.innerHTML='<video id="camera-video" autoplay playsinline muted></video><span class="stage-label">LIVE · 카메라</span><span class="stage-bottom">이미지는 촬영 버튼을 누를 때만 저장됩니다.</span>';$('#camera-video').srcObject=stream;return}if(selected){el.innerHTML=`<img src="${selected.image}" alt="${esc(selected.origin==='synthetic'?'설명용 합성 부품 이미지':selected.name)}"><span class="stage-label">${selected.origin==='synthetic'?'SYNTHETIC · 합성 시연':'INSPECTION IMAGE'}</span><span class="stage-label right">${selected.width} × ${selected.height}</span><span class="stage-bottom">${esc(selected.name)}</span>`}else{el.innerHTML=`<div class="stage-empty"><div class="empty-icon">${icon(source==='camera'?'camera':'image')}</div><strong>${source==='camera'?'검사 카메라를 연결하세요':'검사할 부품 이미지를 등록하세요'}</strong><p>${source==='camera'?'연결 버튼을 누르면 브라우저에서 카메라 사용 권한을 요청합니다.':'촬영 이미지 또는 합성 샘플로 검사와 기록 흐름을 시작할 수 있습니다.'}</p>${btn('합성 샘플 불러오기','sample','small','image')}</div>`}el.insertAdjacentHTML('beforeend','<i class="corner tl"></i><i class="corner tr"></i><i class="corner bl"></i><i class="corner br"></i>')}
function overviewView(){const reviewed=state.records.filter(r=>['양품','불량'].includes(r.review.verdict)).length;return `${head('검사 업무를 한곳에서','카메라 검사부터 데이터 수집, 모델 연결과 검토 이력까지 이어지는 품질 워크스페이스.',btn('새 검사 시작','go-inspect','primary','plus'))}${stats()}<div class="big-note"><strong>현재 공급 범위</strong><br>검사·수집·검토·검색 기능과 모델 연결 인터페이스를 제공합니다. 실제 항공제조 부품 데이터 수집, 학습과 성능 검증은 공급받는 기업이 수행합니다.</div><div class="two-col"><section class="card"><div class="card-head"><h2>현장 도입 흐름</h2><span class="minor">IMPLEMENTATION</span></div><div class="card-body steps">${[['수집 기준 정의','부품·결함 유형과 촬영 환경을 정하고 양품·불량을 수집합니다.'],['데이터 수집 및 라벨 검토','이미지와 LOT, 관찰 내용을 저장하고 담당자가 정답 라벨을 검토합니다.'],['기업 데이터로 학습','Teachable Machine에서 이미지 모델을 학습하고 별도 데이터로 검증합니다.'],['모델 연결 및 제한적 운영','검증된 모델을 연결하고 담당자의 최종 검토와 함께 사용합니다.']].map(([a,b],i)=>`<div class="step"><span class="step-no">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>현재 작업 현황</h2></div><div class="card-body"><div class="notice-row"><span>저장 위치</span><strong>이 기기의 브라우저</strong></div><div class="notice-row"><span>검사 기록</span><strong>${state.records.length}건</strong></div><div class="notice-row"><span>담당자 검토 완료</span><strong>${reviewed}건</strong></div><div class="notice-row"><span>기업 수집 이미지</span><strong>${state.dataset.filter(x=>x.origin!=='synthetic').length}장</strong></div><div class="notice-row"><span>합성 시연 이미지</span><strong>${state.dataset.filter(x=>x.origin==='synthetic').length}장</strong></div><div class="notice-row"><span>검증된 판독 성능</span><strong>아직 측정하지 않음</strong></div><div class="divider"></div>${btn('데이터 수집함 열기','go-dataset','full-btn','layers')}</div></section></div><div class="section-head"><h2>최근 검사 기록</h2></div><div class="card table-wrap">${recordsTable(state.records.slice().reverse().slice(0,5))}</div>`}
function datasetView(){return `${head('데이터 수집','공급받는 기업이 직접 모으는 현장 이미지. 촬영 정보와 정답 라벨을 함께 관리합니다.',btn('수집 데이터 내보내기','export-dataset','','download')+btn('이미지 추가','dataset-upload','primary','plus'))}<div class="status-banner">${icon('layers')}실제 항공제조 데이터셋은 포함되어 있지 않습니다. 합성 시연 이미지는 실제 학습 자료와 분리됩니다.</div><div class="mini-grid"><div>전체 수집<strong>${state.dataset.length}장</strong></div><div>미분류<strong>${state.dataset.filter(x=>x.label==='미분류').length}장</strong></div><div>실제 촬영 · 업로드<strong>${state.dataset.filter(x=>x.origin!=='synthetic').length}장</strong></div></div><div class="toolbar"><input id="search" placeholder="부품 번호, LOT, 파일명 검색" value="${esc(search)}" aria-label="수집 이미지 검색"><select id="filter" aria-label="수집 라벨 필터"><option value="all">모든 라벨</option>${['미분류',...new Set([...state.settings.classes,...state.dataset.map(x=>x.label)])].filter((v,i,a)=>a.indexOf(v)===i).map(x=>`<option value="${esc(x)}" ${filter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div id="dataset-list">${datasetList()}</div><p class="smalltext">내보내기는 이미지 파일, manifest.json, 라벨별 폴더 및 CSV를 담은 ZIP입니다. 촬영 세션 단위의 학습·검증 분리는 기업에서 수행해야 합니다.</p>`}
function datasetList(){const rows=state.dataset.filter(r=>(filter==='all'||r.label===filter)&&`${r.part} ${r.lot} ${r.name}`.toLowerCase().includes(search.toLowerCase()));if(!rows.length)return `<section class="card empty-state">${icon('layers')}<h3>${state.dataset.length?'조건에 맞는 이미지가 없습니다':'아직 수집된 이미지가 없습니다'}</h3><p>실제 부품의 양품·불량 이미지를 수집하거나, 검사 화면에서 촬영한 이미지를 수집함으로 보내세요.</p>${btn('검사 화면으로 이동','go-inspect','primary','camera')}</section>`;return `<div class="gallery">${rows.slice().reverse().map(r=>`<section class="card data-card"><img loading="lazy" src="${r.image}" alt="${esc(r.name)}"><div class="card-body"><div style="display:flex;justify-content:space-between;gap:7px"><h3>${esc(r.part||'부품 미지정')}</h3><span class="pill ${r.origin==='synthetic'?'amber':'gray'}">${r.origin==='synthetic'?'합성 시연':'수집 이미지'}</span></div><div class="data-meta">${esc(r.name)}<br>LOT ${esc(r.lot||'미입력')} · ${localDate(r.createdAt)}</div><label class="field" style="margin-top:10px">수집 라벨<select data-label="${esc(r.id)}">${[...new Set(['미분류',...state.settings.classes,r.label])].map(x=>`<option ${x===r.label?'selected':''}>${esc(x)}</option>`).join('')}</select></label><div class="data-actions"><button class="btn small" data-use="${esc(r.id)}">검사에 사용</button><button class="btn small danger" data-remove="${esc(r.id)}">삭제</button></div></div></section>`).join('')}</div>`}
function historyView(){return `${head('검사 이력','사진, AI 제안과 담당자의 검토 결과를 연결해 과거 사례를 다시 확인합니다.',btn('CSV 내보내기','export-records','','download')+btn('검사 시작','go-inspect','primary','plus'))}<div class="toolbar"><input id="search" placeholder="기록번호, 부품, LOT, 검사자, 관찰 내용 검색" value="${esc(search)}" aria-label="검사 이력 검색"><select id="filter" aria-label="검토 상태 필터"><option value="all">모든 검토 상태</option>${['미검토','양품','불량','재검토'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="card table-wrap" id="history-list">${historyList()}</div><p class="smalltext">시연 기록에는 시연 표시가 보존됩니다. AI 제안과 담당자의 최종 검토는 별도의 값으로 저장됩니다.</p>`}
function historyList(){return recordsTable(state.records.filter(r=>(filter==='all'||r.review.verdict===filter)&&`${r.id} ${r.part} ${r.lot} ${r.inspector} ${r.review.notes}`.toLowerCase().includes(search.toLowerCase())).slice().reverse(),state.records.length?'검색 조건에 맞는 검사 기록이 없습니다. 검색어나 검토 상태를 바꿔 주세요.':'아직 저장된 검사 기록이 없습니다. 사진과 관찰 내용을 첫 기록으로 남겨보세요.')}
function modelView(){return `${head('AI 모델 연결','기업이 수집한 데이터로 학습한 Teachable Machine 이미지 모델을 연결합니다.')}<div class="big-note"><strong>${model?'모델이 연결되어 있습니다.':'현재는 학습 데이터와 모델이 없는 상태입니다.'}</strong><br>카메라 촬영·기록·데이터 수집 기능은 모델 없이 사용할 수 있습니다. 연결한 모델도 별도의 현장 검증을 거쳐야 합니다.</div><div class="two-col"><section class="card"><div class="card-head"><h2>Teachable Machine 모델 불러오기</h2><span class="pill ${model?'':'gray'}">${model?'연결됨':'미연결'}</span></div><div class="card-body"><p class="smalltext">공개 모델 주소를 입력하거나 TensorFlow.js 형식으로 내보낸 파일 3개를 선택하세요. 파일 방식은 이 브라우저에서 읽으며 외부 서버로 업로드하지 않습니다.</p><label class="field">모델 기본 URL<input id="model-url" type="url" value="${esc(state.settings.modelUrl)}" placeholder="https://teachablemachine.withgoogle.com/models/모델ID/"></label><div style="margin-top:12px">${btn('URL 모델 불러오기','load-model-url','primary','cpu')}</div><div class="divider"></div><h3>또는 모델 파일 선택</h3><div class="model-files"><label class="field">모델 구조 model.json<input class="file-input" type="file" id="model-json" accept=".json,application/json"></label><label class="field">가중치 weights.bin<input class="file-input" type="file" id="model-weights" accept=".bin"></label><label class="field">라벨 metadata.json<input class="file-input" type="file" id="model-metadata" accept=".json,application/json"></label></div>${btn('파일 모델 불러오기','load-model-files','primary','upload')}<div class="divider"></div><label class="field">추가 검토를 요청할 출력 기준 <span id="threshold-text">${state.settings.threshold}%</span><input id="threshold" type="range" min="50" max="99" value="${state.settings.threshold}"></label><p class="smalltext">최상위 출력이 기준보다 낮으면 추가 검토를 요청합니다. 이 기준은 현장 검증 없이 합격 기준으로 사용할 수 없습니다.</p></div></section><div class="stack"><section class="card"><div class="card-head"><h2>모델 정보</h2></div><div class="card-body"><div class="notice-row"><span>상태</span><strong>${model?'연결됨':'연결 대기'}</strong></div><div class="notice-row"><span>모델 이름</span><strong>${model?esc(modelName):'—'}</strong></div><div class="notice-row"><span>방식</span><strong>${model?esc(modelOrigin):'—'}</strong></div><div class="notice-row"><span>기능</span><strong>이미지 전체의 클래스 분류</strong></div><div class="notice-row"><span>결함 위치 탐지</span><strong>제공하지 않음</strong></div><div class="notice-row"><span>현장 정확도</span><strong>미검증</strong></div>${model?`<div class="tag-list">${model.getClassLabels().map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>${btn('모델 연결 해제','unload-model','full-btn','')}`:''}</div></section><section class="card"><div class="card-head"><h2>연결 전 확인</h2></div><div class="card-body smalltext">1. 양품·불량 라벨 정의와 전문가 검토<br>2. 촬영 배경·조명·각도 통일<br>3. 동일 부품·촬영 세션 단위 학습/검증 분리<br>4. 미검출·오검출과 미지 유형 확인<br>5. 최종 품질 판정은 담당자 확인<div class="divider"></div><a class="btn full-btn" href="https://teachablemachine.withgoogle.com/train" target="_blank" rel="noopener">Teachable Machine 열기 ${icon('external')}</a></div></section></div></div>`}
function guideView(){return `${head('도입 가이드','프로그램 공급부터 현장 데이터 축적과 모델 검증까지, 기업이 이어갈 작업을 정리했습니다.')}<div class="big-note"><strong>프로젝트 완료 범위</strong><br>외관검사 업무 화면, 카메라·사진 등록, 관찰·검토 이력, 데이터 수집·내보내기 및 모델 연결 기능입니다. 기업 데이터셋, 학습된 판독 모델과 성능 검증 결과는 포함되어 있지 않습니다.</div><div class="two-col"><section class="card"><div class="card-head"><h2>공급 후 기업 수행 단계</h2></div><div class="card-body steps">${[['운영 조건 결정','검사 부품, 결함 유형, 촬영 장치·조명과 허용 기준을 정합니다.'],['이미지와 라벨 수집','부품·LOT·촬영 세션을 기록하고 양품과 불량 사례를 수집합니다. 합성 시연 자료는 제외합니다.'],['학습 및 분리 검증','Teachable Machine 이미지 프로젝트를 만들고 촬영 세션이 겹치지 않는 별도 자료로 검증합니다.'],['모델 연결 및 운영 평가','TensorFlow.js 모델을 내보내 연결하고, 미검출·오검출과 담당자 검토 절차를 평가합니다.']].map(([a,b],i)=>`<div class="step"><span class="step-no">${i+1}</span><div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>참고 도구와 데이터 출처</h2></div>${[
 ['T','Teachable Machine','이미지 분류 모델 학습·TensorFlow.js 내보내기','https://teachablemachine.withgoogle.com/train'],
 ['K','KAMP 인공지능 제조 플랫폼','제조 데이터셋과 제조 AI 적용 사례 조사','https://www.kamp-ai.kr/main'],
 ['A','AI Hub','제조 분야 데이터 후보·이용 조건 조사','https://www.aihub.or.kr/'],
 ['G','Teachable Machine 공식 라이브러리','모델 URL·로컬 파일 불러오기와 이미지 추론','https://github.com/googlecreativelab/teachablemachine-community/tree/master/libraries/image']
 ].map(([l,a,b,url])=>`<a class="resource" href="${url}" target="_blank" rel="noopener"><span class="resource-letter">${l}</span><span><strong>${a}</strong><p>${b}</p></span>${icon('external')}</a>`).join('')}</section></div><section class="card" style="margin-top:20px"><div class="card-head"><h2>저장 및 배포 범위</h2></div><div class="card-body"><p class="smalltext">이 시제품은 사진·기록을 현재 브라우저의 IndexedDB에 보관합니다. 다른 기기와 자동 동기화되지 않으며 사이트 주소가 달라지면 별도 저장소를 사용합니다. 운영 전에 ZIP 백업과 CSV 내보내기를 수행하세요. 서버형 내부 공급 시에는 사내 인증·역할별 권한·중앙 데이터베이스·파일 저장소·백업 정책이 추가로 필요합니다.</p><p class="smalltext">공개 데이터셋은 실제 항공제조사의 결함 분포를 대체하지 않습니다. 이용 허락·재배포·상업적 사용 조건을 확인하고 기업 촬영 데이터로 현장 검증을 진행해야 합니다. 이 프로그램은 최종 정비 적합성이나 운항 가능 여부를 판정하지 않습니다.</p></div></section>`}
function settingsView(){return `${head('워크스페이스 설정','공급받는 기업의 검사 스테이션과 데이터 수집 라벨을 설정합니다.')}<div class="two-col"><section class="card"><div class="card-head"><h2>기본 설정</h2></div><div class="card-body"><div class="form-grid"><label class="field full">워크스페이스 이름<input id="company" value="${esc(state.settings.company)}" maxlength="80"></label><label class="field full">스테이션 이름<input id="station" value="${esc(state.settings.station)}" maxlength="60"></label><label class="field full">수집 라벨 <span class="smalltext">쉼표로 구분</span><textarea id="classes">${esc(state.settings.classes.join(', '))}</textarea></label></div><p class="smalltext">예: 양품, 스크래치, 찍힘, 오염. 수집 라벨을 변경해도 이미 저장한 라벨은 유지됩니다.</p>${btn('설정 저장','settings-save','primary','check')}</div></section><section class="card"><div class="card-head"><h2>백업 및 복원</h2></div><div class="card-body"><p class="smalltext">사진·검사 기록·수집 데이터·설정을 JSON 백업으로 저장합니다. 복원은 검사 기록과 수집 이미지만 추가합니다. 기존 ID와 현재 설정은 유지됩니다. 회사 기밀이 포함된 백업 파일의 보관에 유의하세요.</p><div class="stack">${btn('전체 워크스페이스 백업','backup','','download')}${btn('백업 파일에서 복원','restore','','upload')}</div><div class="divider"></div><div class="notice-row"><span>저장 방식</span><strong>브라우저 IndexedDB</strong></div><div class="notice-row"><span>기기 간 공유</span><strong>자동 공유 안 됨</strong></div><div class="notice-row"><span>모델 파일 보관</span><strong>현재 세션에서만 로드</strong></div></div></section></div>`}
function bind(){
 $$('[data-nav]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();navigate(el.dataset.nav)}));
 $$('[data-action]').forEach(el=>el.addEventListener('click',()=>runAction(el.dataset.action)));
 $$('[data-form]').forEach(el=>el.addEventListener('input',()=>{inspectionForm[el.dataset.form]=el.value}));
 $('#demo-type')?.addEventListener('change',e=>{demoType=e.target.value});
 $('#search')?.addEventListener('input',e=>{search=e.target.value;updateList()});$('#filter')?.addEventListener('change',e=>{filter=e.target.value;updateList()});
 $('#threshold')?.addEventListener('input',async e=>{const value=Number(e.target.value);$('#threshold-text').textContent=value+'%';try{await mutate(()=>state.settings.threshold=value)}catch(err){toast(err.message)}});
 bindRows();
}
function updateList(){if(view==='history')$('#history-list').innerHTML=historyList();else if(view==='dataset')$('#dataset-list').innerHTML=datasetList();bindRows(); $$("#dataset-list [data-action]").forEach(el=>el.onclick=()=>runAction(el.dataset.action))}
function bindRows(){
 $$('[data-record]').forEach(el=>el.onclick=()=>showRecord(el.dataset.record));
 $$('[data-label]').forEach(el=>el.onchange=async()=>{try{await mutate(()=>{state.dataset.find(r=>r.id===el.dataset.label).label=el.value});render();toast('수집 라벨을 저장했습니다.')}catch(e){toast(e.message)}});
 $$('[data-use]').forEach(el=>el.onclick=()=>{const r=state.dataset.find(x=>x.id===el.dataset.use);selected={...r};inspectionForm={...inspectionForm,part:r.part||'',lot:r.lot||''};result=null;navigate('inspect')});
 $$('[data-remove]').forEach(el=>el.onclick=()=>confirmRemove(el.dataset.remove));
}
async function runAction(action){try{
 if(action.startsWith('go-')){navigate(action.slice(3));return}
 switch(action){
 case 'new':stopCamera();selected=null;result=null;inspectionForm={part:'',lot:'',area:'표면 / 가공면',inspector:inspectionForm.inspector,verdict:'미검토',notes:''};render();break;
 case 'sample':await sample();break;
 case 'source-upload':stopCamera();source='upload';render();break;
 case 'source-camera':stopCamera();source='camera';render();break;
 case 'camera':await camera();break;
 case 'stop':stopCamera();render();break;
 case 'capture':await capture();break;
 case 'upload':chooseFiles('image/jpeg,image/png,image/webp',false,async files=>{stopCamera();selected=await readImage(files[0],'upload');result=null;render()});break;
 case 'dataset-upload':chooseFiles('image/jpeg,image/png,image/webp',true,async files=>{if(files.length>30)throw new Error('한 번에 최대 30장까지 추가할 수 있습니다.');const items=[];for(const f of files){const image=await readImage(f,'upload');items.push({...image,id:uid('IMG'),label:'미분류',part:'',lot:'',createdAt:now(),notes:''})}await mutate(()=>state.dataset.push(...items));render();toast(`${items.length}장의 이미지를 수집함에 추가했습니다.`)});break;
 case 'simulate':if(!selected||selected.origin!=='synthetic')throw new Error('합성 샘플에서만 시연 시나리오를 사용할 수 있습니다.');result={kind:'demo',label:demoType,model:'고정 시연 시나리오',scores:[],note:'선택한 시나리오에 따른 고정 결과입니다. 실제 판독 결과가 아닙니다.',createdAt:now()};render();break;
 case 'predict':await predict();break;
 case 'save':await saveRecord();break;
 case 'collect':await collect();break;
 case 'export-records':exportRecords();break;
 case 'export-dataset':await exportDataset();break;
 case 'backup':download(JSON.stringify({schema:'aeroscope-workspace',version:1,exportedAt:now(),...state},null,2),'aeroscope-backup.json','application/json');toast('전체 백업 파일을 내보냈습니다.');break;
 case 'restore':chooseFiles('.json,application/json',false,async files=>{await restoreBackup(await files[0].text());render();toast('새 항목을 백업에서 복원했습니다.');});break;
 case 'load-model-url':await loadModel('url');break;
 case 'load-model-files':await loadModel('files');break;
 case 'unload-model':if(model?.dispose)model.dispose();model=null;modelName='';result=null;render();toast('모델 연결을 해제했습니다.');break;
 case 'settings-save':{const company=$('#company').value.trim(),station=$('#station').value.trim();const classes=[...new Set($('#classes').value.split(',').map(x=>x.trim()).filter(Boolean))];if(!company||!station||!classes.length||classes.length>20)throw new Error('이름과 1~20개의 수집 라벨을 입력하세요.');if(classes.some(x=>x.length>40))throw new Error('라벨은 40자 이하로 입력하세요.');await mutate(()=>Object.assign(state.settings,{company,station,classes}));render();toast('워크스페이스 설정을 저장했습니다.');break}
 }
 }catch(e){console.error(e);toast(e.message||'작업을 완료하지 못했습니다.')}}
function chooseFiles(accept,multiple,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.multiple=multiple;input.onchange=async()=>{if(input.files.length)try{await callback([...input.files])}catch(e){toast(e.message||'파일을 읽지 못했습니다.')}};input.click()}
async function imageElement(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('이미지를 읽을 수 없습니다. JPG, PNG 또는 WEBP 파일을 선택하세요.'));im.src=src})}
async function readImage(file,origin){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('JPG, PNG, WEBP 파일만 지원합니다.');if(file.size>12*1024*1024)throw new Error('이미지 한 장의 크기는 12 MB 이하여야 합니다.');const url=URL.createObjectURL(file);try{const img=await imageElement(url);const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return {image:c.toDataURL('image/jpeg',.88),name:file.name,width:c.width,height:c.height,origin,capturedAt:now()}}finally{URL.revokeObjectURL(url)}}
async function sample(){stopCamera();const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="760" viewBox="0 0 1200 760"><defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="#e6ebea"/><stop offset="1" stop-color="#d6dfdd"/></linearGradient><linearGradient id="metal" x1="0" x2=".8" y2="1"><stop stop-color="#e3e9e6"/><stop offset=".45" stop-color="#aebcba"/><stop offset=".8" stop-color="#ced8d3"/><stop offset="1" stop-color="#9baea9"/></linearGradient><pattern id="brush" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 0h4" stroke="#fff" stroke-opacity=".13"/></pattern><filter id="s"><feDropShadow dx="6" dy="20" stdDeviation="20" flood-color="#627e70" flood-opacity=".25"/></filter></defs><rect width="1200" height="760" fill="url(#bg)"/><g opacity=".35" stroke="#fff"><path d="M0 190h1200M0 380h1200M0 570h1200M300 0v760M600 0v760M900 0v760"/></g><g transform="translate(160,100) rotate(-8 440 270)" filter="url(#s)"><path d="M60 90 710 50Q740 48 754 76L858 401Q867 430 832 437L179 530Q151 534 142 504L24 131Q17 102 60 90Z" fill="#8c9f98"/><path d="M60 75 710 35Q740 33 754 61L858 386Q867 415 832 422L179 515Q151 519 142 489L24 116Q17 87 60 75Z" fill="url(#metal)" stroke="#e5eeea" stroke-width="3"/><path d="M60 75 710 35Q740 33 754 61L858 386Q867 415 832 422L179 515Q151 519 142 489L24 116Q17 87 60 75Z" fill="url(#brush)"/><path d="m172 170 445-40 49 190-432 56Z" fill="#96aaa3" stroke="#e2ebe5" stroke-width="3"/><path d="m192 178 410-35 40 156-400 51Z" fill="#bdcac3"/><g fill="#657d73" stroke="#dbe5df" stroke-width="9"><circle cx="101" cy="134" r="22"/><circle cx="682" cy="104" r="22"/><circle cx="786" cy="369" r="22"/><circle cx="207" cy="443" r="22"/></g><g stroke="#738f83" stroke-width="2" opacity=".4"><path d="m278 244 219-25m-216 31 215-25m-212 31 214-25m-210 31 213-25"/></g><path d="m383 201 34 27-12 32 45 22" fill="none" stroke="#6d7d75" stroke-width="3"/><path d="m386 201 34 27-12 32 45 22" fill="none" stroke="#f2f4ec" stroke-width="2"/><text x="286" y="413" font-size="21" font-family="monospace" fill="#6e8579" letter-spacing="5">AEROSCOPE / DEMO</text></g><text x="38" y="725" font-size="18" font-family="sans-serif" fill="#84958e">SYNTHETIC REFERENCE · NOT A MANUFACTURING DATASET</text></svg>`;const img=await imageElement('data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg))));const c=document.createElement('canvas');c.width=1200;c.height=760;c.getContext('2d').drawImage(img,0,0);selected={image:c.toDataURL('image/jpeg',.92),name:'합성 가공 부품 · 설명용 샘플.jpg',width:1200,height:760,origin:'synthetic',capturedAt:now()};inspectionForm.part='DEMO-BRKT-001';inspectionForm.lot='DEMO-LOT-01';result=null;render();toast('설명용 합성 샘플입니다. 실제 기업 데이터가 아닙니다.')}
async function camera(){if(!navigator.mediaDevices?.getUserMedia)throw new Error('카메라는 HTTPS 또는 localhost에서 지원됩니다. 사진 업로드를 사용하세요.');try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280},height:{ideal:720}},audio:false});source='camera';render()}catch(e){stopCamera();const messages={NotAllowedError:'카메라 권한이 허용되지 않았습니다. 주소창 권한을 확인하거나 사진을 업로드하세요.',NotFoundError:'연결된 카메라를 찾지 못했습니다. 사진 업로드로 진행할 수 있습니다.',NotReadableError:'다른 프로그램이 카메라를 사용 중입니다. 연결을 확인하세요.'};throw new Error(messages[e.name]||'카메라를 연결하지 못했습니다. 장치 연결과 브라우저 권한을 확인하세요.')}}
async function capture(){const video=$('#camera-video');if(!video?.videoWidth)throw new Error('카메라 영상이 준비될 때까지 잠시 기다려 주세요.');const c=document.createElement('canvas');const scale=Math.min(1,1600/video.videoWidth);c.width=Math.round(video.videoWidth*scale);c.height=Math.round(video.videoHeight*scale);c.getContext('2d').drawImage(video,0,0,c.width,c.height);selected={image:c.toDataURL('image/jpeg',.9),name:`camera-${Date.now()}.jpg`,width:c.width,height:c.height,origin:'camera',capturedAt:now()};stopCamera();result=null;render();toast('이미지를 촬영했습니다. 관찰 내용을 입력해 저장하세요.')}
function validForm(){if(!selected)throw new Error('먼저 사진을 업로드하거나 촬영하세요.');for(const [k,name] of [['part','부품 번호'],['lot','LOT / 일련번호'],['inspector','검사자']])if(!inspectionForm[k].trim())throw new Error(`${name}을 입력하세요.`)}
async function saveRecord(){validForm();const record={id:uid('INS'),part:inspectionForm.part.trim(),lot:inspectionForm.lot.trim(),area:inspectionForm.area,inspector:inspectionForm.inspector.trim(),createdAt:now(),capturedAt:selected.capturedAt,origin:selected.origin,image:selected.image,imageName:selected.name,width:selected.width,height:selected.height,ai:result?structuredClone(result):null,review:{verdict:inspectionForm.verdict,notes:inspectionForm.notes.trim(),updatedAt:now()},reviewHistory:[]};await mutate(()=>state.records.push(record));result=null;selected=null;inspectionForm={...inspectionForm,verdict:'미검토',notes:''};render();toast(`검사 기록 ${record.id}을 저장했습니다.`)}
async function collect(){if(!selected)throw new Error('먼저 수집할 이미지를 선택하세요.');const label=$('#collection-label')?.value||'미분류';await mutate(()=>state.dataset.push({...selected,id:uid('IMG'),part:inspectionForm.part.trim(),lot:inspectionForm.lot.trim(),label,notes:inspectionForm.notes,createdAt:now()}));render();toast('이미지와 라벨을 수집함에 저장했습니다.')}
function showRecord(id){const r=state.records.find(r=>r.id===id);if(!r)return;const modal=$('#modal');modal.innerHTML=`<div class="modal-head"><h2>검사 기록 상세</h2><button class="close" aria-label="닫기">×</button></div><div class="modal-body"><img src="${r.image}" alt="저장된 검사 사진"><span class="pill ${r.origin==='synthetic'?'amber':'gray'}">${r.origin==='synthetic'?'합성 시연 이미지':'수집 이미지'}</span><p><strong>${esc(r.part)}</strong> · ${esc(r.lot)}</p><div class="notice-row"><span>기록번호</span><strong>${esc(r.id)}</strong></div><div class="notice-row"><span>촬영 부위</span><strong>${esc(r.area)}</strong></div><div class="notice-row"><span>검사자 · 일시</span><strong>${esc(r.inspector)} · ${localDate(r.createdAt)}</strong></div><div class="notice-row"><span>AI 제안</span><strong>${r.ai?esc(r.ai.label)+' / '+(r.ai.kind==='demo'?'고정 시연값':'미검증 모델 출력'):'모델 미연결 · 판독 안 함'}</strong></div><div class="divider"></div><div class="form-grid"><label class="field full">담당자 검토 결과<select id="review-verdict">${['미검토','양품','불량','재검토'].map(x=>`<option ${r.review.verdict===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full">관찰 · 검토 의견<textarea id="review-notes" maxlength="3000">${esc(r.review.notes)}</textarea></label></div><p class="smalltext">검토 수정 이력 ${r.reviewHistory.length}건. AI 제안은 수정하지 않습니다.</p>${r.reviewHistory.slice(-3).reverse().map(x=>`<p class="smalltext">${localDate(x.updatedAt)} · ${esc(x.verdict)} · ${esc(x.notes)}</p>`).join('')}<div class="review-actions"><button class="btn" id="record-collect">수집함에 추가</button><button class="btn primary" id="review-save">검토 저장</button></div></div>`;modal.showModal();$('.close',modal).onclick=()=>modal.close();$('#review-save').onclick=async()=>{const verdict=$('#review-verdict').value,notes=$('#review-notes').value.trim();try{await mutate(()=>{const target=state.records.find(x=>x.id===id);target.reviewHistory.push(structuredClone(target.review));target.review={verdict,notes,updatedAt:now()}});modal.close();render();toast('검토 결과와 수정 이력을 저장했습니다.')}catch(e){toast(e.message)}};$('#record-collect').onclick=async()=>{try{await mutate(()=>state.dataset.push({id:uid('IMG'),image:r.image,name:r.imageName,origin:r.origin,width:r.width,height:r.height,capturedAt:r.capturedAt,createdAt:now(),part:r.part,lot:r.lot,label:'미분류',notes:r.review.notes}));toast('검사 이미지를 미분류 수집함에 추가했습니다.')}catch(e){toast(e.message)}}}
function confirmRemove(id){const modal=$('#modal');modal.innerHTML=`<div class="modal-head"><h2>수집 이미지 삭제</h2><button class="close" aria-label="닫기">×</button></div><div class="modal-body"><p>이 수집 이미지를 삭제할까요? 검사 기록의 사진은 유지됩니다. 삭제 전 ZIP 또는 전체 백업으로 보관할 수 있습니다.</p><div class="review-actions"><button class="btn" id="cancel-delete">취소</button><button class="btn danger" id="confirm-delete">수집 이미지 삭제</button></div></div>`;modal.showModal();$('.close',modal).onclick=$('#cancel-delete').onclick=()=>modal.close();$('#confirm-delete').onclick=async()=>{try{await mutate(()=>state.dataset=state.dataset.filter(x=>x.id!==id));modal.close();render();toast('수집 이미지를 삭제했습니다.')}catch(e){toast(e.message)}}}
let scriptPromise;
function loadScript(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>{s.remove();reject(new Error('AI 라이브러리를 불러오지 못했습니다. 프로그램의 vendor 파일과 서버 연결을 확인하세요.'))};document.head.append(s)})}
async function tm(){if(window.tmImage)return window.tmImage;if(!scriptPromise)scriptPromise=(async()=>{await loadScript('./vendor/tf.min.js');await loadScript('./vendor/teachablemachine-image.min.js');return window.tmImage})().catch(e=>{scriptPromise=null;throw e});return scriptPromise}
async function loadModel(mode){if(busy)return;let url,files;if(mode==='url'){const raw=$('#model-url').value.trim();try{url=new URL(raw)}catch{throw new Error('올바른 모델 기본 URL을 입력하세요.')}if(url.protocol!=='https:')throw new Error('HTTPS 모델 주소를 사용하세요.');if(!url.pathname.endsWith('/'))url.pathname+='/'}else{files=[$('#model-json').files[0],$('#model-weights').files[0],$('#model-metadata').files[0]];if(files.some(f=>!f))throw new Error('model.json, weights.bin, metadata.json 파일을 모두 선택하세요.');if(files.reduce((s,f)=>s+f.size,0)>150*1024*1024)throw new Error('모델 파일은 합계 150 MB 이하로 준비하세요.');let meta;try{meta=JSON.parse(await files[2].text())}catch{throw new Error('metadata.json 형식을 확인하세요.')}if(!Array.isArray(meta.labels)||meta.labels.length<2)throw new Error('최소 두 개 클래스가 있는 이미지 모델을 선택하세요.')}
 busy=true;toast('이미지 분류 모델을 불러오는 중입니다…');let loaded;try{const library=await tm();loaded=mode==='url'?await library.load(new URL('model.json',url).href,new URL('metadata.json',url).href):await library.loadFromFiles(...files);if(loaded.getTotalClasses()<2)throw new Error('모델에 최소 두 개 클래스가 필요합니다.');if(mode==='url')await mutate(()=>state.settings.modelUrl=url.href);if(model?.dispose)model.dispose();model=loaded;loaded=null;modelName=mode==='url'?'Teachable Machine 이미지 모델':files[0].name;modelOrigin=mode==='url'?'HTTPS URL':'로컬 파일';result=null;render();toast('모델을 연결했습니다. 현장 성능은 별도 검증이 필요합니다.')}catch(e){if(loaded?.dispose)loaded.dispose();throw new Error('모델 연결 실패: '+(e.message||'파일 형식, 주소와 네트워크를 확인하세요.'))}finally{busy=false}}
async function predict(){if(busy)return;if(!selected)throw new Error('분석할 이미지를 먼저 선택하세요.');if(!model)throw new Error('학습된 모델을 먼저 연결하세요. 합성 샘플은 별도의 시연 버튼을 사용할 수 있습니다.');const predictionSource=selected;busy=true;toast('모델로 이미지를 분석하는 중입니다…');try{const img=await imageElement(predictionSource.image);const scores=(await model.predict(img,false)).map(x=>({className:String(x.className),probability:Number(x.probability)})).filter(x=>Number.isFinite(x.probability)).sort((a,b)=>b.probability-a.probability);if(!scores.length)throw new Error('모델의 출력값을 확인할 수 없습니다.');if(selected!==predictionSource){toast('검사 이미지가 변경되어 이전 분석 결과를 적용하지 않았습니다.');return}result={kind:'model',label:scores[0].className,scores,model:modelName,createdAt:now(),note:scores[0].probability*100<state.settings.threshold?'출력 기준 미만 · 추가 검토 필요':'미검증 모델의 참고 출력 · 최종 검토 필요'};busy=false;render()}finally{busy=false}}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(value=>{let s=String(value??'');if(/^[\s]*[=+@-]|^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n')}
function exportRecords(){if(!state.records.length)throw new Error('내보낼 검사 기록이 없습니다.');const rows=[['기록번호','검사일시','부품번호','LOT','촬영부위','검사자','이미지출처','AI제안','AI결과종류','모델','최종검토','관찰의견','검토일시'],...state.records.map(r=>[r.id,r.createdAt,r.part,r.lot,r.area,r.inspector,r.origin,r.ai?.label||'',r.ai?.kind||'none',r.ai?.model||'',r.review.verdict,r.review.notes,r.review.updatedAt])];download(csv(rows),'aeroscope-inspection-history.csv','text/csv;charset=utf-8');toast('검사 이력을 CSV로 내보냈습니다.')}
// Build a standards-compliant, uncompressed ZIP without a network dependency.
const crcTable=Array.from({length:256},(_,n)=>{let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;return c>>>0});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0}
function uints(n){return new DataView(new ArrayBuffer(n))}
function zip(entries){const encoder=new TextEncoder();let offset=0;const parts=[],central=[];for(const [name,data] of entries){const filename=encoder.encode(name),bytes=typeof data==='string'?encoder.encode(data):data,crc=crc32(bytes);const h=uints(30);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,33,true);h.setUint32(14,crc,true);h.setUint32(18,bytes.length,true);h.setUint32(22,bytes.length,true);h.setUint16(26,filename.length,true);parts.push(h.buffer,filename,bytes);const c=uints(46);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,33,true);c.setUint32(16,crc,true);c.setUint32(20,bytes.length,true);c.setUint32(24,bytes.length,true);c.setUint16(28,filename.length,true);c.setUint32(42,offset,true);central.push(c.buffer,filename);offset+=30+filename.length+bytes.length}const centralSize=central.reduce((s,v)=>s+v.byteLength,0),end=uints(22);end.setUint32(0,0x06054b50,true);end.setUint16(8,entries.length,true);end.setUint16(10,entries.length,true);end.setUint32(12,centralSize,true);end.setUint32(16,offset,true);return new Blob([...parts,...central,end.buffer],{type:'application/zip'})}
const safeName=s=>s.replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,80)||'unlabeled';
async function exportDataset(){if(!state.dataset.length)throw new Error('내보낼 수집 이미지가 없습니다.');const entries=[],manifest=[];for(const item of state.dataset){const folder=item.origin==='synthetic'?'synthetic-demo':item.label==='미분류'?'unlabeled':'collected';const path=`${folder}/${safeName(item.label)}/${safeName(item.id)}.jpg`;const raw=atob(item.image.split(',')[1]);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));entries.push([path,bytes]);const {image,...meta}=item;manifest.push({...meta,path,trainingApproved:false})}entries.push(['manifest.json',JSON.stringify({schema:'aeroscope-dataset',version:1,exportedAt:now(),items:manifest},null,2)]);entries.push(['labels.csv',csv([['ID','파일경로','라벨','부품','LOT','출처','촬영일시','관찰내용'],...manifest.map(x=>[x.id,x.path,x.label,x.part,x.lot,x.origin,x.capturedAt,x.notes])])]);entries.push(['README.txt','AEROSCOPE 수집 이미지 내보내기\n\ncollected: 기업이 직접 수집한 이미지. 라벨 검토 후 사용하세요.\nunlabeled: 정답 라벨 검토 전 자료입니다.\nsynthetic-demo: 설명용 합성 이미지. 현장 학습·성능 검증에서 제외하세요.\n\n동일 부품·LOT·촬영 세션의 유사 사진은 학습과 평가에 동시에 넣지 마세요.\n이 ZIP은 검증된 항공제조 데이터셋이 아닙니다. 데이터 이용 권한과 기업 보안 기준을 확인하세요.']);download(zip(entries),'aeroscope-collected-images.zip');toast('이미지와 라벨을 ZIP으로 내보냈습니다.')}
function validImage(s){return typeof s==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s)&&s.length<8*1024*1024}
async function restoreBackup(text){if(text.length>100*1024*1024)throw new Error('백업 파일이 너무 큽니다.');const backup=JSON.parse(text);if(backup.schema!=='aeroscope-workspace'||backup.version!==1||!Array.isArray(backup.records)||!Array.isArray(backup.dataset))throw new Error('AEROSCOPE 전체 백업 파일을 선택하세요.');if(backup.records.length+backup.dataset.length>10000)throw new Error('한 번에 복원할 항목이 너무 많습니다.');for(const r of backup.records){if(typeof r.id!=='string'||!validImage(r.image)||!r.review||!['미검토','양품','불량','재검토'].includes(r.review.verdict)||!Array.isArray(r.reviewHistory)||!Number.isFinite(Date.parse(r.createdAt)))throw new Error('검사 기록의 형식이 올바르지 않습니다.')}for(const r of backup.dataset){if(typeof r.id!=='string'||!validImage(r.image)||typeof r.label!=='string'||!Number.isFinite(Date.parse(r.createdAt)))throw new Error('수집 데이터의 형식이 올바르지 않습니다.')}await mutate(()=>{const recordIds=new Set(state.records.map(x=>x.id)),imageIds=new Set(state.dataset.map(x=>x.id));for(const r of backup.records)if(!recordIds.has(r.id)){state.records.push(r);recordIds.add(r.id)}for(const r of backup.dataset)if(!imageIds.has(r.id)){state.dataset.push(r);imageIds.add(r.id)}})}
window.addEventListener('beforeunload',stopCamera);
window.addEventListener('pagehide',stopCamera);
try{await load();render()}catch(e){$('#app').innerHTML=`<main style="padding:60px;max-width:700px;margin:auto"><h1>브라우저 저장소를 열 수 없습니다</h1><p>비공개 모드 또는 저장소 제한을 확인하고 일반 브라우저에서 다시 열어 주세요. 사진을 보존할 수 없는 상태에서는 작업을 시작하지 않습니다.</p></main>`;console.error(e)}

